using HRM.Models;
using HRM.Models.Recruitment;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace HRM.Api.Data.EntityConfigurations;

public sealed class RecruitmentOperationsMapping : IEntityTypeConfiguration<RecruitmentRequisition>, IEntityTypeConfiguration<RecruitmentPositionReservation>, IEntityTypeConfiguration<RecruitmentVacancy>
{
    public void Configure(EntityTypeBuilder<RecruitmentRequisition> b) { b.ToTable("RM_RecruitmentRequisitions"); b.HasKey(x=>x.Id); b.Property(x=>x.Reference).HasMaxLength(80).IsRequired(); b.Property(x=>x.EmploymentType).HasMaxLength(60).IsRequired(); b.Property(x=>x.RecruitmentType).HasMaxLength(60).IsRequired(); b.Property(x=>x.Reason).HasMaxLength(2000).IsRequired(); b.Property(x=>x.Status).HasMaxLength(40).IsRequired(); b.Property(x=>x.PositionSnapshotJson).HasMaxLength(8000).IsRequired(); b.Property(x=>x.Version).IsConcurrencyToken(); b.HasIndex(x=>x.Reference).IsUnique(); b.HasIndex(x=>new{x.OrganisationId,x.Status,x.CreatedAtUtc}); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<OrganisationStructure>().WithMany().HasForeignKey(x=>x.OrganisationStructureId).OnDelete(DeleteBehavior.Restrict); b.HasOne<PositionMatrix>().WithMany().HasForeignKey(x=>x.PositionMatrixId).OnDelete(DeleteBehavior.Restrict); b.HasOne<RecruitmentPolicyVersion>().WithMany().HasForeignKey(x=>x.RecruitmentPolicyVersionId).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x=>x.RequestedByUserId).OnDelete(DeleteBehavior.Restrict); b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<RecruitmentPositionReservation> b) { b.ToTable("RM_RecruitmentPositionReservations"); b.HasKey(x=>x.Id); b.Property(x=>x.Status).HasMaxLength(30).IsRequired(); b.Property(x=>x.Version).IsConcurrencyToken(); b.HasIndex(x=>new{x.PositionMatrixId,x.Status}); b.HasIndex(x=>new{x.RecruitmentRequisitionId,x.Status}).IsUnique().HasFilter("[Status] = 'Active'"); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<PositionMatrix>().WithMany().HasForeignKey(x=>x.PositionMatrixId).OnDelete(DeleteBehavior.Restrict); b.HasOne<RecruitmentRequisition>().WithMany().HasForeignKey(x=>x.RecruitmentRequisitionId).OnDelete(DeleteBehavior.Restrict); b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<RecruitmentVacancy> b) { b.ToTable("RM_RecruitmentVacancies"); b.HasKey(x=>x.Id); b.Property(x=>x.Reference).HasMaxLength(80).IsRequired(); b.Property(x=>x.Status).HasMaxLength(40).IsRequired(); b.Property(x=>x.AdvertisementSnapshotJson).HasMaxLength(16000).IsRequired(); b.Property(x=>x.Version).IsConcurrencyToken(); b.HasIndex(x=>x.Reference).IsUnique(); b.HasIndex(x=>new{x.OrganisationId,x.Status,x.ClosingAtUtc}); b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<RecruitmentRequisition>().WithMany().HasForeignKey(x=>x.RecruitmentRequisitionId).OnDelete(DeleteBehavior.Restrict); b.HasOne<RecruitmentPolicyVersion>().WithMany().HasForeignKey(x=>x.RecruitmentPolicyVersionId).OnDelete(DeleteBehavior.Restrict); b.HasOne<PositionMatrix>().WithMany().HasForeignKey(x=>x.PositionMatrixId).OnDelete(DeleteBehavior.Restrict); b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict); }
}
